components.css:
.ds-btn-green{display:inline-block;border:none;cursor:pointer;font-family:var(--font-sans, 'DM Sans', Inter, system-ui, sans-serif);font-size:1rem;font-weight:600;line-height:1.5rem;padding:12px 24px;border-radius:9999px;transition:color .2s,background-color .2s,border-color .2s;background:var(--color-green-mid, #526855);color:var(--color-paper, #ffffff);box-shadow:0 1px 3px 0 rgb(37 37 37 / 5%);}
.ds-btn-green:hover{background:var(--color-green, #384033);}
.ds-btn-green:focus-visible{outline:2px solid var(--color-green, #384033);outline-offset:2px;}

.ds-btn-outline{display:inline-block;border:none;cursor:pointer;font-family:var(--font-sans, 'DM Sans', Inter, system-ui, sans-serif);font-size:1rem;font-weight:600;line-height:1.5rem;padding:12px 24px;border-radius:9999px;transition:color .2s,background-color .2s,border-color .2s;background:transparent;color:var(--color-ink-soft, #5c5c5c);border:1px solid color-mix(in srgb, var(--color-green-mid, #526855) 40%, transparent);}
.ds-btn-outline:hover{border-color:var(--color-green-mid, #526855);color:var(--color-green-mid, #526855);}
.ds-btn-outline:focus-visible{outline:2px solid var(--color-green-mid, #526855);outline-offset:2px;}

.ds-quiz-stack{display:flex;flex-direction:column;gap:8px;font-family:var(--font-sans, 'DM Sans', Inter, system-ui, sans-serif);max-width:420px;}
.ds-quiz-option{position:relative;overflow:hidden;border-radius:12px;border:1px solid color-mix(in srgb, var(--color-ink, #252525) 10%, transparent);padding:12px 16px;text-align:left;font-size:.875rem;line-height:1.25rem;background:transparent;color:var(--color-ink-soft, #5c5c5c);cursor:pointer;transition:color .2s,border-color .2s;}
.ds-quiz-option::before{content:"";position:absolute;inset:0;transform-origin:left;transform:scaleX(0);background:var(--color-green-soft, #e8ece7);transition:transform .28s cubic-bezier(.16,1,.3,1);}
.ds-quiz-option>span{position:relative;}
.ds-quiz-option:hover{border-color:color-mix(in srgb, var(--color-green-mid, #526855) 50%, transparent);}
.ds-quiz-option.is-selected{border-color:var(--color-green-mid, #526855);color:var(--color-ink, #252525);}
.ds-quiz-option.is-selected::before{transform:scaleX(1);}
.ds-quiz-option:focus-visible{outline:2px solid var(--color-green-mid, #526855);outline-offset:2px;}

.ds-divider{display:flex;align-items:center;gap:16px;font-family:var(--font-sans, 'DM Sans', Inter, system-ui, sans-serif);color:var(--color-gold-dark, #a15c17);}
.ds-divider::before,.ds-divider::after{content:"";height:1px;flex:1;background:color-mix(in srgb, var(--color-gold, #ca9e52) 40%, transparent);}
.ds-divider h2{margin:0;min-width:0;font-size:1.5rem;line-height:2rem;font-weight:700;color:var(--color-ink, #252525);}

.ds-nav{position:relative;display:flex;align-items:center;gap:32px;font-family:var(--font-sans, 'DM Sans', Inter, system-ui, sans-serif);background:linear-gradient(135deg,var(--color-green, #384033),var(--color-green-mid, #526855) 45%,var(--color-gold-dark, #a15c17));padding:24px;border-radius:12px;}
.ds-nav::before{content:'';position:absolute;inset:0;border-radius:12px;pointer-events:none;background-image:linear-gradient(to bottom,rgb(37 37 37 / 0%) 0,rgb(37 37 37 / 72%) 1.5rem,rgb(37 37 37 / 72%) calc(100% - 1.5rem),rgb(37 37 37 / 0%) 100%);}
.ds-nav-link{position:relative;z-index:1;display:inline-flex;align-items:center;padding-bottom:4px;font-size:1.25rem;font-weight:500;text-decoration:none;color:var(--color-paper, #ffffff);text-shadow:0 1px 6px rgb(0 0 0 / 75%);transition:color .2s;}
.ds-nav-link:hover{color:var(--color-gold-light, #e3c48a);}
.ds-nav-link.is-active{color:var(--color-gold-light, #e3c48a);font-weight:700;}
.ds-nav-indicator{position:absolute;left:0;bottom:0;height:2px;width:100%;border-radius:9999px;background:var(--color-gold-light, #e3c48a);box-shadow:0 1px 6px rgb(0 0 0 / 60%);}

.ds-area-flip{font-family:var(--font-sans, 'DM Sans', Inter, system-ui, sans-serif);display:block;width:100%;max-width:360px;text-align:left;perspective:1000px;}
.ds-area-flip-inner{position:relative;display:block;aspect-ratio:4/3;transform-style:preserve-3d;transition:transform 500ms ease;}
@media (hover: hover) and (pointer: fine){.ds-area-flip:hover .ds-area-flip-inner,.ds-area-flip:focus-visible .ds-area-flip-inner{transform:rotateY(180deg);}}
.ds-area-flip.is-flipped .ds-area-flip-inner{transform:rotateY(180deg);}
.ds-area-face{position:absolute;inset:0;overflow:hidden;border-radius:12px;background:var(--color-paper, #fff);backface-visibility:hidden;}
.ds-area-front img{display:block;width:100%;height:100%;object-fit:cover;}
.ds-area-badge{position:absolute;left:12px;right:12px;bottom:12px;padding:8px 12px;border-radius:6px;background:rgb(37 37 37 / 70%);color:var(--color-paper, #fff);font-size:.875rem;font-weight:700;}
.ds-area-back{display:flex;flex-direction:column;justify-content:center;transform:rotateY(180deg);padding:20px;}
.ds-area-title{font-size:1.125rem;line-height:1.75rem;font-weight:700;color:var(--color-green-mid, #526855);}
.ds-area-text{margin-top:8px;font-size:.875rem;line-height:1.25rem;color:var(--color-ink-soft, #5c5c5c);}

.ds-comm-hero{position:relative;overflow:hidden;background:var(--color-green, #384033);padding:96px 24px;text-align:center;color:var(--color-paper, #fff);font-family:var(--font-sans, 'DM Sans', Inter, system-ui, sans-serif);}
.ds-comm-hero-img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;}
.ds-comm-hero-scrim{position:absolute;inset:0;background:linear-gradient(to top, rgb(37 37 37 / 85%), rgb(37 37 37 / 40%) 60%, rgb(37 37 37 / 10%));}
.ds-comm-hero-text{position:relative;max-width:48rem;margin:0 auto;}
.ds-comm-hero-eyebrow{font-size:.875rem;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--color-gold-light, #e3c48a);}
